#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-05-12

# ============================================================================
# CC Version Floor Consistency
# ============================================================================
# Asserts every derived declaration of the CC supported floor agrees with the
# single source of truth in shared/cc-support.json.
#
# Derived files checked:
#   - src/hooks/src/lib/cc-version-matrix.ts   (MIN_CC_VERSION constant)
#   - CLAUDE.md                                (Version section)
#   - src/skills/doctor/references/version-compatibility.md (overview)
#   - src/skills/*/SKILL.md                    (compatibility: frontmatter, #1963)
#
# Failure mode caught: someone bumps cc-support.json but forgets to run
# scripts/stamp-cc-support.mjs (or edits a derived file manually), leaving
# users running CC < floor silently bypassing feature gates.
#
# SKILL.md mode: STRICT by default (post adoption-sweep). Below-floor skill
# compatibility fields fail the test. Override with SKILL_COMPAT_STRICT=0 if
# you have a legitimate temporary need to ship a skill above the floor.
#
# Issues: #1765 (M137) | #1963 (extended SKILL.md check)
# ============================================================================
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"

if [[ -t 1 ]]; then
    RED='\033[0;31m'; GREEN='\033[0;32m'; NC='\033[0m'
else
    RED=''; GREEN=''; NC=''
fi

PASS=0
FAIL=0
log_pass() { echo -e "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
log_fail() { echo -e "  ${RED}✗${NC} $1 — $2"; FAIL=$((FAIL + 1)); }

echo "CC Version Floor Consistency (M137 #1765)"
echo "========================================="

SUPPORT_JSON="$PROJECT_ROOT/shared/cc-support.json"
if [[ ! -f "$SUPPORT_JSON" ]]; then
    log_fail "shared/cc-support.json" "missing"
    exit 1
fi

SOT=$(node -e "console.log(JSON.parse(require('fs').readFileSync('$SUPPORT_JSON','utf8')).supported_floor)")
if ! [[ "$SOT" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
    log_fail "shared/cc-support.json supported_floor" "not a semver: '$SOT'"
    exit 1
fi
log_pass "SoT supported_floor = $SOT"

# 1. src/hooks/src/lib/cc-version-matrix.ts :: MIN_CC_VERSION
MATRIX_VAL=$(grep -E "export const MIN_CC_VERSION = '" "$PROJECT_ROOT/src/hooks/src/lib/cc-version-matrix.ts" | head -1 | sed -E "s/.*'([0-9.]+)'.*/\1/")
if [[ "$MATRIX_VAL" == "$SOT" ]]; then
    log_pass "cc-version-matrix.ts MIN_CC_VERSION = $MATRIX_VAL"
else
    log_fail "cc-version-matrix.ts MIN_CC_VERSION" "got '$MATRIX_VAL', want '$SOT' (run: node scripts/stamp-cc-support.mjs)"
fi

# 2. CLAUDE.md :: Version section
CLAUDE_VAL=$(grep -E "^\- \*\*Current\*\*:.*\*\*Claude Code\*\*: >= " "$PROJECT_ROOT/CLAUDE.md" | head -1 | sed -E "s/.*>= ([0-9.]+).*/\1/")
if [[ "$CLAUDE_VAL" == "$SOT" ]]; then
    log_pass "CLAUDE.md Claude Code floor = $CLAUDE_VAL"
else
    log_fail "CLAUDE.md Claude Code floor" "got '$CLAUDE_VAL', want '$SOT' (run: node scripts/stamp-cc-support.mjs)"
fi

# 3. doctor version-compatibility.md :: every derived floor declaration
#
# Three markers are checked and a MISSING marker is a FAIL, never a skip.
#
# History (2026-09-06, #3933). This check used to grep for the string
# "Minimum supported CC version: **X.Y.Z**", which has never existed in the
# file: scripts/stamp-cc-support.mjs writes "OrchestKit requires Claude Code
# >= X.Y.Z." instead. The no-match branch then logged a PASS, so the check
# reported green while reading no version at all. It sat that way across the
# floor moving 2.1.220 to 2.1.277, which is how the floor-table row and three
# doctor examples were left asserting 2.1.220 while cc-support.json said
# 2.1.277. A check whose absent-marker branch passes cannot fail in the way it
# exists to fail, so both the marker and that branch are fixed here.
DOCTOR_MD="$PROJECT_ROOT/src/skills/doctor/references/version-compatibility.md"
if [[ ! -f "$DOCTOR_MD" ]]; then
    log_fail "doctor version-compatibility.md" "missing"
else
    DOCTOR_CONTENT=$(cat "$DOCTOR_MD")

    # 3a. Overview line, stamped by scripts/stamp-cc-support.mjs.
    RE_OVERVIEW='OrchestKit requires Claude Code >= ([0-9]+\.[0-9]+\.[0-9]+)'
    if [[ "$DOCTOR_CONTENT" =~ $RE_OVERVIEW ]]; then
        DOCTOR_VAL="${BASH_REMATCH[1]}"
        if [[ "$DOCTOR_VAL" == "$SOT" ]]; then
            log_pass "doctor version-compatibility.md overview = $DOCTOR_VAL"
        else
            log_fail "doctor version-compatibility.md overview" "got '$DOCTOR_VAL', want '$SOT' (run: node scripts/stamp-cc-support.mjs)"
        fi
    else
        log_fail "doctor version-compatibility.md overview" "marker absent; the stamper writes 'OrchestKit requires Claude Code >= X.Y.Z.' and nothing matched it"
    fi

    # 3b. Floor-table row. This row's own text claims it mirrors cc-support.json,
    #     so an unenforced mirror is a claim, not an enforcement.
    RE_FLOORROW='\| >= ([0-9]+\.[0-9]+\.[0-9]+) \| \*\*Minimum \(current floor\)\*\*'
    if [[ "$DOCTOR_CONTENT" =~ $RE_FLOORROW ]]; then
        ROW_VAL="${BASH_REMATCH[1]}"
        if [[ "$ROW_VAL" == "$SOT" ]]; then
            log_pass "doctor version-compatibility.md floor row = $ROW_VAL"
        else
            log_fail "doctor version-compatibility.md floor row" "got '$ROW_VAL', want '$SOT' (run: node scripts/stamp-cc-support.mjs)"
        fi
    else
        log_fail "doctor version-compatibility.md floor row" "'| >= X.Y.Z | **Minimum (current floor)**' row absent"
    fi

    # 3c. Doctor output examples. Users copy these blocks, so a stale number here
    #     tells somebody on an unsupported build that they are fine.
    #
    #     Two-step on purpose. Under `set -euo pipefail` a single
    #     `grep ... | grep -v ...` pipeline cannot distinguish "no example lines
    #     exist" from "every example line is correct": both surface as rc=1, and
    #     the first of those is the vacuous pass this whole block exists to stop.
    #     So count the lines first and fail on zero, then judge their contents.
    EX_RE='^(- Minimum required: |Claude Code: [0-9]+\.[0-9]+\.[0-9]+ \(OK\))'
    EX_LINES=""
    EX_RC=0
    if ! EX_LINES=$(grep -nE "$EX_RE" "$DOCTOR_MD"); then EX_RC=$?; fi
    EX_TOTAL=$(printf '%s' "$EX_LINES" | awk 'NF{n++} END{print n+0}')

    if [[ "$EX_RC" -gt 1 ]]; then
        log_fail "doctor version-compatibility.md examples" "could not observe (grep rc=$EX_RC)"
    elif [[ "$EX_TOTAL" -eq 0 ]]; then
        log_fail "doctor version-compatibility.md examples" "zero example lines matched '$EX_RE'; the probe cannot pass vacuously"
    else
        BAD_LINES=""
        BAD_RC=0
        if ! BAD_LINES=$(printf '%s\n' "$EX_LINES" | grep -vF "$SOT"); then BAD_RC=$?; fi
        if [[ "$BAD_RC" -gt 1 ]]; then
            log_fail "doctor version-compatibility.md examples" "could not observe (grep -v rc=$BAD_RC)"
        elif [[ -n "$BAD_LINES" ]]; then
            log_fail "doctor version-compatibility.md examples" "$(printf '%s' "$BAD_LINES" | tr '\n' ';') want '$SOT' (run: node scripts/stamp-cc-support.mjs)"
        else
            log_pass "doctor version-compatibility.md examples = $SOT ($EX_TOTAL lines)"
        fi
    fi
fi

# 4. src/skills/*/SKILL.md :: compatibility: frontmatter field (#1963)
#
# Scans all skill SKILL.md files. Per-skill compatibility floors are advisory
# in WARN mode (the default) — they surface count + names of below-floor skills
# without blocking CI. Set SKILL_COMPAT_STRICT=1 to escalate below-floor skills
# to fails (intended to flip on after the adoption-sweep PR brings them up).
SKILL_COMPAT_STRICT="${SKILL_COMPAT_STRICT:-1}"
SKILLS_DIR="$PROJECT_ROOT/src/skills"
if [[ -d "$SKILLS_DIR" ]]; then
    total=0
    below=0
    missing=0
    below_names=()
    IFS='.' read -r sot_maj sot_min sot_pat <<< "$SOT"
    for skill_md in "$SKILLS_DIR"/*/SKILL.md; do
        [[ -f "$skill_md" ]] || continue
        total=$((total + 1))
        skill_name=$(basename "$(dirname "$skill_md")")
        # silent: best-effort  no-match exit-1 expected; handled by empty branch below
        compat_line=$(grep -m1 -E "^compatibility:" "$skill_md" || true)
        if [[ -z "$compat_line" ]]; then
            missing=$((missing + 1))
            continue
        fi
        if [[ "$compat_line" =~ ([0-9]+)\.([0-9]+)\.([0-9]+) ]]; then
            sk_maj="${BASH_REMATCH[1]}"; sk_min="${BASH_REMATCH[2]}"; sk_pat="${BASH_REMATCH[3]}"
            if (( sk_maj < sot_maj )) || \
               (( sk_maj == sot_maj && sk_min < sot_min )) || \
               (( sk_maj == sot_maj && sk_min == sot_min && sk_pat < sot_pat )); then
                below=$((below + 1))
                below_names+=("$skill_name@${sk_maj}.${sk_min}.${sk_pat}")
            fi
        fi
    done

    if [[ $missing -gt 0 ]]; then
        log_pass "SKILL.md compatibility: $missing of $total skills missing field (WARN-only)"
    fi
    if [[ $below -gt 0 ]]; then
        if [[ "$SKILL_COMPAT_STRICT" == "1" ]]; then
            log_fail "SKILL.md compatibility floors" "$below of $total skills below SoT ($SOT)"
            printf '      below-floor: %s\n' "${below_names[@]:0:5}"
            if (( below > 5 )); then
                echo "      ... and $((below - 5)) more"
            fi
        else
            log_pass "SKILL.md compatibility: $below of $total skills below SoT ($SOT) — WARN-only (SKILL_COMPAT_STRICT=1 to fail)"
        fi
    else
        log_pass "SKILL.md compatibility: all $total skills at or above SoT ($SOT)"
    fi
fi

# 5. .claude-plugin/marketplace.json :: engine field must NOT exist
#
# `engine` used to be a hand-maintained, untested machine-readable install gate
# in marketplace.json — it drifted below the governed floor twice before being
# made a stamp target. #3349 retired it entirely: `claude plugin validate
# --strict` flags it as an unknown field CC ignores at load time, so the
# CC-version floor now lives solely in shared/cc-support.json. This assertion
# guards against it silently creeping back in.
MARKETPLACE_JSON="$PROJECT_ROOT/.claude-plugin/marketplace.json"
if [[ -f "$MARKETPLACE_JSON" ]]; then
    if node -e "process.exit('engine' in JSON.parse(require('fs').readFileSync('$MARKETPLACE_JSON','utf8')) ? 1 : 0)"; then
        log_pass "marketplace.json has no engine field (retired #3349)"
    else
        log_fail "marketplace.json engine field" "field must not exist — the CC-version floor lives in shared/cc-support.json only"
    fi
fi

# 6. .github/workflows/plugin-validation.yml :: CC install pins (#4686)
#
# The CC Plugin Validate and restricted smoke jobs install Claude Code to run
# `claude plugin validate` and the smoke lane. Their comments said "pinned to
# our supported floor", but the version was a literal (2.1.251) that nothing
# stamped or checked, so it stayed behind when the floor moved to 2.1.277 and
# CI validated the plugin on a build users are not allowed to run.
#
# Every `@anthropic-ai/claude-code@<version>` reference must either be the
# literal SoT floor or a non-literal read of supported_floor from
# shared/cc-support.json. Zero references is a FAIL, never a vacuous pass.
#
# scan_cc_pins <workflow-yml>: prints one line per bad pin.
#   rc 0 = every pin is floor-fed, rc 1 = at least one bad pin,
#   rc 2 = the file could not be observed (grep error or zero pin references).
# Two scoping rules, both measured as holes in HOLD 6108025314:
#   * Per step. The awk window opens at the pin's own `- name:` or `- uses:`
#     step start, so a jq read in an EARLIER job cannot feed a pin whose own
#     step lost the assignment (the second-job removal shape stayed green).
#   * Code before `#` only, anchored at end of line. A literal left as
#     `CC_FLOOR=2.1.251` with the jq read inside a trailing comment fails, and
#     so does `|| CC_FLOOR=2.1.251` after the read: nothing but spaces may
#     follow the closing parenthesis.
scan_cc_pins() {
    local yml="$1"
    local pin_lines pin_rc=0 pin_total ref pin_var pin_no feed feed_code bad=0
    pin_lines=""
    if ! pin_lines=$(grep -nE '@anthropic-ai/claude-code@' "$yml"); then pin_rc=$?; fi
    pin_total=$(printf '%s' "$pin_lines" | awk 'NF{n++} END{print n+0}')
    if [[ "$pin_rc" -gt 1 ]]; then
        echo "could not observe (grep rc=$pin_rc)"
        return 2
    elif [[ "$pin_total" -eq 0 ]]; then
        echo "zero @anthropic-ai/claude-code@ references; the probe cannot pass vacuously"
        return 2
    fi
    while IFS= read -r pin_line; do
        [[ -n "$pin_line" ]] || continue
        ref="${pin_line#*@anthropic-ai/claude-code@}"
        if [[ "$ref" =~ ^([0-9]+\.[0-9]+\.[0-9]+) ]]; then
            if [[ "${BASH_REMATCH[1]}" != "$SOT" ]]; then
                echo "line ${pin_line%%:*} installs ${BASH_REMATCH[1]}, want the floor '$SOT' (read supported_floor from shared/cc-support.json)"
                bad=$((bad + 1))
            fi
        elif [[ "$ref" =~ ^\$\{?([A-Za-z_][A-Za-z0-9_]*) ]]; then
            # A variable pin: the LAST non-comment assignment of that variable
            # inside the pin's own step must be the jq read of supported_floor.
            # The step start is the most recent `- name:` or `- uses:` line.
            # Only a command-start assignment counts: `echo CC_FLOOR=$(jq ...)`
            # prints the value, it does not feed the pin (CodeRabbit 4241672749).
            pin_var="${BASH_REMATCH[1]}"
            pin_no="${pin_line%%:*}"
            feed=$(awk -v n="$pin_no" -v v="$pin_var" '
                NR < n && /^[[:space:]]*-[[:space:]]+(name|uses):/ {step = NR; last = ""}
                NR < n && NR > step && $0 !~ /^[[:space:]]*#/ && $0 ~ ("^[[:space:]]*" v "=") {last = $0}
                END {print last}' "$yml")
            # `#` starts a comment; whatever follows it is prose, not the
            # assignment. Judging only the code before it, a literal pin whose
            # jq text sits in a trailing comment can no longer satisfy the
            # anchored match.
            feed_code="${feed%%#*}"
            if ! [[ "$feed_code" =~ ^[[:space:]]*$pin_var=\$\(jq\ -e?r\ \'\.supported_floor\'\ shared/cc-support\.json\)[[:space:]]*$ ]]; then
                echo "line $pin_no installs \$$pin_var, but its last in-step assignment is '${feed_code#"${feed_code%%[![:space:]]*}"}', want $pin_var=\$(jq -er '.supported_floor' shared/cc-support.json) inside the pin's own step"
                bad=$((bad + 1))
            fi
        else
            echo "line ${pin_line%%:*} is neither a literal floor nor a variable fed from supported_floor in shared/cc-support.json"
            bad=$((bad + 1))
        fi
    done <<< "$pin_lines"
    [[ $bad -eq 0 ]]
}

# CC_FLOOR_PV_YML overrides the scan target so the fault shapes in
# fixtures/cc-version-floor/ (and ad-hoc copies of the real file) can be
# replayed through this same check.
PV_YML="${CC_FLOOR_PV_YML:-$PROJECT_ROOT/.github/workflows/plugin-validation.yml}"
if [[ ! -f "$PV_YML" ]]; then
    log_fail "plugin-validation.yml" "missing"
else
    SCAN_OUT=""
    SCAN_RC=0
    SCAN_OUT=$(scan_cc_pins "$PV_YML") || SCAN_RC=$?
    if [[ "$SCAN_RC" -gt 1 ]]; then
        log_fail "plugin-validation.yml CC pins" "$SCAN_OUT"
    elif [[ "$SCAN_RC" -eq 0 ]]; then
        log_pass "plugin-validation.yml CC pins track the floor ($(grep -cE '@anthropic-ai/claude-code@' "$PV_YML") references)"
    else
        while IFS= read -r pin_err; do
            if [[ -n "$pin_err" ]]; then
                log_fail "plugin-validation.yml CC pin" "$pin_err"
            fi
        done <<< "$SCAN_OUT"
    fi
fi

# 6c. The shapes that brought #4686 back must each FAIL the pin scan.
#     HOLD 6108025314 measured the first three green on the merged tree;
#     CodeRabbit 4241672749 adds the echo shape: `echo CC_FLOOR=$(jq ...)`
#     prints the floor instead of assigning it. The fixtures under
#     fixtures/cc-version-floor/ carry one shape each; a scan that passes
#     any of them cannot fail in the way it exists to fail.
FIXTURE_DIR="$SCRIPT_DIR/fixtures/cc-version-floor"
for shape in trailing-comment or-fallback second-job-missing echo-assignment; do
    fx="$FIXTURE_DIR/$shape.yml"
    if [[ ! -f "$fx" ]]; then
        log_fail "check 6 fixture ($shape)" "missing fixture file"
        continue
    fi
    FX_RC=0
    scan_cc_pins "$fx" >/dev/null 2>&1 || FX_RC=$?
    if [[ "$FX_RC" -eq 1 ]]; then
        log_pass "check 6 rejects the $shape fixture"
    else
        log_fail "check 6 fixture ($shape)" "scan rc=$FX_RC (want 1) on a shape that restores #4686"
    fi
done

# 6b. plugin-validation.yml :: a failed CC install must fail the step (#4686 follow-up).
# "2>/dev/null || true" on the install made a broken install look like "CLI not available"
# and skipped plugin validation with a green job.
if [[ -f "$PV_YML" ]]; then
    set +e
    SOFT=$(grep -nE '(claude-code@|install\.cjs|INSTALL_CJS).*\|\| *true' "$PV_YML")
    SOFT_RC=$?
    set -e
    if [[ "$SOFT_RC" -gt 1 ]]; then
        log_fail "plugin-validation.yml CC install" "could not observe (grep rc=$SOFT_RC)"
    elif [[ -n "$SOFT" ]]; then
        while IFS= read -r soft_line; do
            log_fail "plugin-validation.yml CC install" "line ${soft_line%%:*} swallows a failed install with || true"
        done <<< "$SOFT"
    else
        log_pass "plugin-validation.yml CC installs fail loudly (no || true)"
    fi
fi

# 7. Idempotence: stamper should produce zero mutations on an already-stamped tree.
set +e
STAMP_OUT=$(node "$PROJECT_ROOT/scripts/stamp-cc-support.mjs" 2>&1)
STAMP_RC=$?
set -e
if [[ $STAMP_RC -ne 0 ]]; then
    log_fail "stamp-cc-support.mjs" "exited rc=$STAMP_RC — $STAMP_OUT"
elif echo "$STAMP_OUT" | grep -qE "^stamp-cc-support: 0 mutation"; then
    log_pass "stamp-cc-support.mjs is idempotent (no pending mutations)"
elif echo "$STAMP_OUT" | grep -qE "mutation\(s\) applied"; then
    MUT_COUNT=$(echo "$STAMP_OUT" | grep -oE "[0-9]+ mutation" | head -1 | grep -oE "[0-9]+")
    log_fail "stamper not idempotent" "$MUT_COUNT pending mutation(s); commit + re-run"
else
    log_pass "stamp-cc-support.mjs ran (no mutation summary in output; fallback OK)"
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ $FAIL -eq 0 ]] || exit 1
